package dev.xclipse.gpulab;
import java.io.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.regex.*;
import java.nio.charset.StandardCharsets;
final class Libraries {
 static final Pattern TOKENS=Pattern.compile("(?:VK_[A-Z0-9]+_[A-Za-z0-9_]{3,160}|GL_[A-Z0-9]+_[A-Za-z0-9_]{3,160}|EGL_[A-Z0-9]+_[A-Za-z0-9_]{3,160}|CL_[A-Za-z0-9_]{3,160}|vk[A-Z][A-Za-z0-9_]{4,160}|(?:gfx11[0-9a-z]+|v_wmma_[A-Za-z0-9_]+|v_mfma_[A-Za-z0-9_]+|wave32|wave64))");
 static String scan(){StringBuilder b=new StringBuilder("[Bibliotecas GPU: leitura ELF e strings, nao prova de suporte]\n");TreeSet<String> paths=new TreeSet<>();for(String d:new String[]{"/vendor/lib64/hw","/vendor/lib64/egl","/vendor/lib64","/odm/lib64/hw","/odm/lib64/egl","/odm/lib64","/system/lib64","/system_ext/lib64"}){File[] files=new File(d).listFiles();if(files==null){b.append("Diretorio indisponivel: ").append(d).append('\n');continue;}for(File f:files){String n=f.getName().toLowerCase(Locale.ROOT);if(n.endsWith(".so")&&(n.contains("vulkan")||n.contains("gles")||n.contains("egl")||n.contains("opencl")||n.contains("xclipse")||n.contains("sgpu")||n.contains("mali")||n.contains("drm")))paths.add(f.getAbsolutePath());}}
 try(BufferedReader r=new BufferedReader(new FileReader("/proc/self/maps"))){String line;while((line=r.readLine())!=null){int p=line.indexOf('/');if(p>=0){String s=line.substring(p);String n=s.toLowerCase(Locale.ROOT);if(s.endsWith(".so")&&(n.contains("vulkan")||n.contains("gles")||n.contains("opencl")||n.contains("sgpu")))paths.add(s);}}}catch(IOException ignored){}
 for(String path:paths){File f=new File(path);b.append("\n").append(path).append(" bytes=").append(f.length()).append('\n');try(InputStream in=new BufferedInputStream(new FileInputStream(f))){MessageDigest md=MessageDigest.getInstance("SHA-256");TreeSet<String> tokens=new TreeSet<>();byte[] buf=new byte[65536];StringBuilder word=new StringBuilder();int n;long read=0;boolean first=true;while((n=in.read(buf))!=-1){if(first){first=false;if(n>=20&&buf[0]==0x7f&&buf[1]=='E'&&buf[2]=='L'&&buf[3]=='F')b.append("ELF class=").append(buf[4]&255).append(" endian=").append(buf[5]&255).append(" machine=").append((buf[5]==1?(buf[18]&255)|((buf[19]&255)<<8):((buf[18]&255)<<8)|(buf[19]&255))).append('\n');}md.update(buf,0,n);read+=n;for(int i=0;i<n;i++){char c=(char)(buf[i]&255);if(c>=32&&c<=126){if(word.length()<1024)word.append(c);}else{collect(word,tokens);word.setLength(0);}}}collect(word,tokens);b.append("SHA256=");for(byte v:md.digest())b.append(String.format(Locale.ROOT,"%02x",v&255));b.append(" read=").append(read).append("\nIndicios (max 6000): ").append(tokens.size()).append('\n');for(String t:tokens)b.append(t).append('\n');}catch(Exception e){b.append("Leitura indisponivel: ").append(e).append('\n');}}
 return b.toString();}
 static String compare(String vulkan,String elf){if(vulkan.isEmpty())return "\nExecute Vulkan profundo primeiro para comparar extensoes.\n";Set<String> advertised=new HashSet<>(),found=new TreeSet<>();Pattern ext=Pattern.compile("^VK_[A-Z0-9]+_[A-Za-z0-9_]+$");for(String line:vulkan.split("\n")){int pos=line.indexOf(" r");if(pos>0){String name=line.substring(0,pos);if(ext.matcher(name).matches())advertised.add(name);}}for(String line:elf.split("\n"))if(ext.matcher(line).matches()&&!line.endsWith("_EXTENSION_NAME")&&!line.endsWith("_SPEC_VERSION"))found.add(line);found.removeAll(advertised);StringBuilder b=new StringBuilder("\n[Strings VK_ ausentes da lista anunciada: pistas, nao extensoes ocultas comprovadas]\n");for(String name:found)b.append(name).append('\n');return b.toString();}
 static void collect(StringBuilder s,Set<String> out){if(s.length()<5||out.size()>=6000)return;Matcher m=TOKENS.matcher(s);while(m.find()&&out.size()<6000)out.add(m.group());}
}
